return ['domain'=>'tranzly','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'sq','project-id-version'=>'tranzly','pot-creation-date'=>'2026-09-26T14:03:23+00:00','po-revision-date'=>'2026-09-26T14:03:23+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Tranzly'=>'Tranzly','https://zinndigital.com/wordpress-plugins/tranzly'=>'https://zinndigital.com/wordpress-plugins/tranzly','Multilingual WordPress, one post per language: linked translations of posts, pages, categories, media text, widgets and the site title, with your old Tranzly translations imported.'=>'WordPress Shumëgjuhësh, një postim për çdo gjuhë: përkthime të lidhura të postimeve, faqeve, kategorive, tekstit të mediave, miniaplikacioneve dhe titullit të faqes, me përkthimet tuaja të vjetra të Tranzly të importuara.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','AI providers'=>'Ofruesit e AI','The makers of ChatGPT. A good all-rounder.'=>'Krijuesit e ChatGPT. Një zgjedhje e mirë e gjithanshme.','The makers of Claude. Strong at writing and careful reasoning.'=>'Krijuesit e Claude. Të fortë në shkrim dhe në arsyetim të kujdesshëm.','Google\'s Gemini models. Fast and inexpensive.'=>'Modelet Gemini të Google. Të shpejta dhe të lira.','A European AI company with fast, inexpensive models.'=>'Një kompani evropiane e inteligjencës artificiale me modele të shpejta dhe të lira.','Low-cost models that are good at writing and code.'=>'Modele me kosto të ulët që janë të mira në shkrim dhe kod.','One key for models from many different providers.'=>'Një çelës për modele nga shumë ofrues të ndryshëm.','Any service that works like OpenAI\'s API, including a model running on your own computer or server.'=>'Çdo shërbim që funksionon si API-ja e OpenAI, duke përfshirë një model që ekzekutohet në kompjuterin ose serverin tuaj.','General (used when nothing more specific is set)'=>'Të përgjithshme (përdoret kur nuk është caktuar ndonjë më specifik)','Writing and rewriting'=>'Shkrim dhe rishkrim','Translation'=>'Përkthimi','Code and CSS'=>'Kodi dhe CSS','Sorry, you are not allowed to access this page.'=>'Na vjen keq, nuk ju lejohet të hyni në këtë faqe.','These settings are shared by every plugin that uses them: %s.'=>'Këto cilësime ndahen nga çdo shtojcë që i përdor ato: %s.','Your keys are encrypted in this site\'s database and are only ever sent to the provider you chose — never to us.'=>'Çelësat tuaj janë të enkoduar në bazën e të dhënave të kësaj faqeje dhe i dërgohen vetëm ofruesit që keni zgjedhur ju — kurrë tek ne.','Step 1 of 2: choose an AI provider'=>'Hapi 1 nga 2: zgjidhni një ofrues të AI','You bring your own key, so you pay the provider directly for what you use. Not sure? Any of these works well; you can add more later.'=>'Ju sillni çelësin tuaj, kështu që i paguani ofruesit direkt për atë që përdorni. Nuk jeni të sigurt? Secila prej këtyre funksionon mirë; mund të shtoni të tjera më vonë.','Next'=>'Para','Step 2 of 2: connect %s'=>'Hapi 2 nga 2: lidhni %s','Enter the address of your OpenAI-compatible service, ending in /v1. A key is only needed if the service asks for one.'=>'Vendosni adresën e shërbimit tuaj të pajtueshëm me OpenAI, që përfundon në /v1. Një çelës nevojitet vetëm nëse shërbimi kërkon një të tillë.','Open %s and sign in (or create a free account).'=>'Hapni %s dhe hyni (ose krijoni një llogari falas).','the %s API keys page'=>'faqja e çelësave API %s','Create a new key and copy it.'=>'Krijo një çelës të ri dhe kopjoje atë.','Paste it below and press "Save and test". We send one tiny request to check it works.'=>'Ngjite atë më poshtë dhe shtyp "Ruaj dhe testo". Ne dërgojmë një kërkesë të vogël për të kontrolluar se funksionon.','Most providers need a little credit on the account before a key works: %s.'=>'Shumë ofrues kanë nevojë për pak kredi në llogari përpara se një çelës të funksionojë: %s.','add credit'=>'shto kredi','← Choose a different provider'=>'← Zgjidhni një ofrues tjetër','Address'=>'Adresa','Saved key ends in …%s — paste a new one to replace it'=>'Çelësi i ruajtur përfundon në …%s — ngjitni një të ri për ta zëvendësuar','Key (optional)'=>'Çelësi (opsionale)','API key'=>'Çelësi i API-së','Save and test'=>'Ruaj dhe provo','Providers'=>'Ofruesit','Provider'=>'Ofruesi','Status'=>'Statusi','Key'=>'Çelësi','Get a key'=>'Merr një çelës','Test'=>'Test','Remove'=>'Hiq','Saved by a newer plugin version: update this plugin, or enter the key again.'=>'Ruajtur nga një version më i ri i shtojcës: përditësoni këtë shtojcë ose futni sërish çelësin.','The saved key can no longer be opened (the site\'s security keys changed). Enter it again.'=>'Çelësi i ruajtur nuk mund të hapet më (çelësat e sigurisë së faqes kanë ndryshuar). Futeni përsëri.','Not connected'=>'I lidhur','Connected — last test passed %s'=>'Lidhur — testimi i fundit kaloi %s','Last test failed: %s'=>'Testi i fundit dështoi: %s','Connected — not tested yet'=>'I lidhur — ende i paprovuar','Which model to use'=>'Cilin model të përdoret','★ marks our recommendation for that task. The list includes every model your key can use, read live from the provider.'=>'★ shënon rekomandimin tonë për atë detyrë. Lista përfshin çdo model që çelësi juaj mund të përdorë, i lexuar drejtpërdrejt nga ofruesi.','— Recommended for the provider —'=>'— Rekomandohet për ofruesin —','Save models'=>'Ruaj modelet','Refresh the model lists from the providers'=>'Rifresko listat e modeleve nga furnizuesit','best quality'=>'cilësia më e mirë','lowest cost'=>'kosto më e ulët','fastest'=>'më i shpejti','Add a model yourself'=>'Shto një model vetë','A model came out today? Paste its exact name to use it straight away.'=>'Një model doli sot? Ngjitni emrin e tij të saktë për ta përdorur menjëherë.','Model name'=>'Emri i modelit','Add model'=>'Shto model','Recommended models list'=>'Lista e modeleve të rekomanduara','The recommended models list could not be verified, so no recommendations are shown. Reinstall the plugin, or turn on daily updates below.'=>'Lista e modeleve të rekomanduara nuk mund të verifikohej, ndaj nuk shfaqet asnjë rekomandim. Riinstaloni spin-in (plugin) ose aktivizoni përditësimet ditore më poshtë.','The list in use was published on %s. Each plugin update brings a fresh one.'=>'Lista në përdorim është publikuar më %s. Çdo përditësim i shtojcës sjell një të re.','Also check Zinn Digital® once a day for an updated list.'=>'Gjithashtu kontrolloni Zinn Digital® një herë në ditë për një listë të përditësuar.','Only a plain download request is sent: no key, no site address, nothing about your content. The list is signed, and a list that fails the signature check is ignored.'=>'Dërgohet vetëm një kërkesë e thjeshtë shkarkimi: asnjë çelës, asnjë adresë faqeje, asgjë rreth përmbajtjes suaj. Lista është e nënshkruar dhe një listë që dështon në kontrollin e nënshkrimit shpërfillet.','Last checked %1$s: %2$s.'=>'Kontrolluar për herë të fundit %1$s: %2$s.','Save, and check now if turned on'=>'Ruaje dhe kontrollo tani nëse është i aktivizuar','a newer list was installed'=>'një listë më e re u instalua','already up to date'=>'tashmë i përditësuar','the download failed the signature check and was ignored'=>'shkarkimi dështoi në kontrollin e nënshkrimit dhe u ignorua','Zinn Digital® could not be reached; the current list stays in use'=>'Zinn Digital® nuk mund të arrihej; lista aktuale mbetet në përdorim','turned off'=>'fikur','Open'=>'Hap','Check their status page'=>'Kontrolloni faqen e tyre të statusit','Open your billing page'=>'Hapni faqen tuaj të faturimit','Open your API keys page'=>'Hapni faqen e çelësave tuaj API','Open the AI settings'=>'Hape cilësimet e AI','Sorry, you are not allowed to do that.'=>'Më vjen keq, nuk ju lejohet ta bëni këtë.','Unknown provider.'=>'Ofrues i panjohur.','Enter the address of your service, for example http://localhost:11434/v1.'=>'Vendosni adresën e shërbimit tuaj, për shembull http://localhost:11434/v1.','That does not look like an API key. Copy it again, without spaces.'=>'Kjo nuk duket si një çelës API. Kopjoje përsëri, pa hapësira.','Paste your API key first.'=>'Ngjitni çelësin tuaj të API-së së pari.','Key removed.'=>'Çelësi u hoq.','Models saved.'=>'Modelet u ruajtën.','Enter the model\'s exact name, for example as the provider\'s documentation writes it.'=>'Futni emrin e saktë të modelit, për shembull siç shkruhet në dokumentacionin e ofruesit.','Added %s. Choose it under "Which model to use".'=>'U shtua %s. Zgjidhni atë te "Cilin model të përdorni".','Model removed.'=>'Modeli u hoq.','Daily updates are off. The list that came with the plugin is used.'=>'Përditësimet ditore janë të çaktivizuara. Përdoret lista që erdhi me shtojcën.','Checked: %s.'=>'Ikontrolluar: %s.','Model lists refreshed.'=>'Listat e modeleve u freskuan.','Your AI key was saved by a newer version of one of your plugins. Update this plugin, or enter the key again in the AI settings.'=>'Çelësi juaj i AI u ruajt nga një version më i ri i njërit prej shtojcave tuaja. Përditësoni këtë shtojcë, ose futeni sërish çelësin te cilësimet e AI.','Your saved AI key can no longer be opened (the site\'s security keys changed). Enter it again in the AI settings.'=>'Çelësi juaj i ruajtur i AI-së nuk mund të hapet më (çelësat e sigurisë së faqes kanë ndryshuar). Futeni përsëri te cilësimet e AI-së.','AI is not set up yet. Add a key for an AI provider in the AI settings.'=>'AI nuk është konfiguruar ende. Shtoni një çelës për një ofrues AI në cilësimet e AI.','No model is chosen for this task. Pick one in the AI settings.'=>'Asnjë model nuk është zgjedhur për këtë detyrë. Zgjidhni një te cilësimet e AI.','That AI provider is not supported by this version of the plugin.'=>'Ky ofrues i AI nuk mbështetet nga ky version i shtojcës.','This site could not reach your AI service. Check that it is running and that its address is reachable from your web server (a service on your own computer is not reachable from a hosted site).'=>'Kjo faqe nuk mundi të arrinte te shërbimi juaj i AI. Kontrolloni që ai është duke punuar dhe se adresa e tij është e arritshme nga serveri juaj i uebit (një shërbim në kompjuterin tuaj nuk është i arritshëm nga një faqe e pritur në host).','This site could not reach %s. Check their status page; if they are up, your host may be blocking outgoing connections, or the address is wrong.'=>'Kjo faqe nuk mundi të arrinte te %s. Kontrolloni faqen e tyre të statusit; nëse ata janë aktivë, strehuesi juaj mund të jetë duke bllokuar lidhjet dalëse, ose adresa është e gabuar.','%s says your account has no credit or quota left. Add credit or raise your limit in your account with them, then try again.'=>'%s thotë se llogaria juaj nuk ka më asnjë kredi apo kuotë të mbetur. Shtoni kredi ose rritni kufirin tuaj në llogarinë tuaj me ta, pastaj provoni përsëri.','%s did not accept your key. It may be mistyped, revoked or expired. Create a new key and paste it here.'=>'%s nuk e pranoi çelësin tuaj. Mund të jetë shkruar gabim, i revokuar ose i skaduar. Krijoni një çelës të ri dhe ngjiteni këtu.','%s refused this request for your key. The key may not have access to this model or feature, or your account needs verifying.'=>'%s refuzoi këtë kërkesë për çelësin tuaj. Çelësi mund të mos ketë qasje në këtë model ose funksionalitet, ose llogaria juaj ka nevojë për verifikim.','The model "%1$s" is not available from %2$s for your key. Choose another model in the AI settings.'=>'Modeli "%1$s" nuk është i disponueshëm nga %2$s për çelësin tuaj. Zgjidhni një model tjetër te cilësimet e AI.','Your %2$s plan does not include the model "%1$s". Choose another model in the AI settings, or upgrade your plan with them.'=>'Pani Jau %2$s nuk përfshin modelin "%1$s". Zgjidhni një model tjetër te cilësimet e AI, ose përmirësoni planin tuaj me ta.','%s is limiting how fast your key can send requests. Wait a minute and try again, or raise your rate limit with them.'=>'%s po kufizon shpejtësinë me të cilën çelësi juaj mund të dërgojë kërkesa. Prisni një minutë dhe provoni përsëri, ose rritni kufirin tuaj të shpejtësisë me ta.','%s is having problems right now (an outage or overload on their side). Nothing is wrong with your settings. Try again shortly.'=>'%s po përjeton probleme në këtë moment (një ndërprerje ose mbingarkesë në anën e tyre). Nuk ka asnjë problem me cilësimet tuaja. Provoni sërish pas pak.','The AI request failed for a reason we could not identify. Try again; if it keeps happening, contact support with the details below.'=>'Kërkesa e AI dështoi për një arsye që nuk mundëm ta identifikonim. Provoni përsëri; nëse vazhdon të ndodhë, kontaktoni mbështetjen me detajet e mëposhtme.','The AI provider answered in a form this plugin could not read. Try again; if it keeps happening, choose another model or contact support.'=>'Ofruesi i AI u përgjigj në një formë që ky shtojcë nuk mund ta lexonte. Provojeni përsëri; nëse kjo vazhdon të ndodhë, zgjidhni një model tjetër ose kontaktoni mbështetjen.','Custom (OpenAI-compatible)'=>'E personalizuar (në përputhje me OpenAI)','Save a key for this provider first.'=>'Ruani një çelës për këtë ofrues fillimisht.','Your key works, but the provider lists no text model for it. Add a model yourself below.'=>'Çelësi juaj funksionon, por ofruesi nuk liston asnjë model teksti për të. Shtoni vetë një model më poshtë.','Connected. %1$s answered using %2$s. Your AI features are ready to use.'=>'Lidhur. %1$s u përgjigj duke përdorur %2$s. Veçoritë tuaja të AI janë gati për t\'u përdorur.','Your user role is not allowed to use AI on this site. Ask an administrator.'=>'Roli juaj i përdoruesit nuk lejohet të përdorë AI në këtë faqe. Kontaktoni një administrator.','This site has reached its monthly AI spending limit. An administrator can raise it in the AI settings.'=>'Ky sajt ka arritur kufirin e tij mujor të shpenzimeve për AI. Një administrator mund ta rrisë atë te cilësimet e AI.','This site has reached its monthly limit of AI requests. An administrator can raise it in the AI settings.'=>'Kjo faqe ka arritur kufirin e saj mujor të kërkesave për AI. Një administrator mund ta rrisë atë te cilësimet e AI.','Usage and cost'=>'Përdorimi dhe kostoja','The log, limits and role permissions apply to AI used through: %s.'=>'Regjistri, kufizimet dhe lejet e roleve zbatohen për inteligjencën artificiale të përdorur përmes: %s.','Costs are approximate, worked out from published prices; a model with no known price counts as zero.'=>'Kostot janë të përafërta, të llogaritura nga çmimet e publikuara; një model pa çmim të njohur llogaritet si zero.','This month: %1$s requests, about %2$s.'=>'Këtë muaj: %1$s kërkesa, rreth %2$s.','When'=>'Kur','Who'=>'Kush','Used for'=>'Përdoret për','Model'=>'Modeli','Tokens in / out'=>'Tokenë në / dalë','About'=>'Rreth','Result'=>'Rezultati','No AI requests have been made yet.'=>'Nuk është bërë ende asnjë kërkesë për AI.','Done'=>'Kryer','Limits and permissions'=>'Kufizimet dhe lejet','Monthly spending limit (US dollars)'=>'Kufiri mujor i shpenzimeve (dollarë US)','Leave empty for no limit. AI stops for the rest of the month once the approximate cost reaches it.'=>'Lëreni bosh për pa kufi. Inteligjenca artificiale ndalet për pjesën e mbetur të muajit sapo kostoja e përafërsuar të arrijë atje.','Monthly request limit'=>'Kufizimi mujor i kërkesave','Leave empty for no limit.'=>'Lëreni bosh për të mos pasur kufizim.','Who may use AI'=>'Kush mund të përdorë AI','Tick none to let everyone who can use the plugin\'s features use AI. Administrators can always use it.'=>'Mos zgjidhni asgjë për t\'i lejuar të gjithë ata që mund të përdorin veçoritë e shtojcës të përdorin AI. Administratorët mund ta përdorin gjithmonë.','Save limits and permissions'=>'Ruaj kufijtë dhe lejet','Limits and permissions saved.'=>'Kufizimet dhe lejet u ruajtën.','That language is not one of this site\'s languages.'=>'Kjo gjuhë nuk është një nga gjuhët e kësaj faqeje.','A translation must be the same kind of content as the original.'=>'Një përkthim duhet të jetë i të njëjtit lloj përmbajtjeje si origjinali.','Choose one of the site\'s other languages.'=>'Zgjidhni një nga gjuhët e tjera të faqes.','The admin screen\'s scripts are missing from this copy of the plugin. Reinstall it from a released package.'=>'Skriptet e ekranit të administratorit mungojnë në këtë kopje të shtojcës. Ristalojeni nga një paketë e lëshuar.','This screen needs JavaScript.'=>'Këtij ekrani i duhet JavaScript.','Choose a language'=>'Zgjidhni një gjuhë','Upgrade'=>'Përmirëso','Pricing'=>'Çmimet','Start Trial'=>'Fillo provën','Account'=>'Llogaria','Contact Us'=>'Na Kontaktoni','Affiliation'=>'Përkatësia','the kind of softwarePlugin'=>'Shtojcë','greetingHey %s,'=>'Përshëndetje %s,','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info. This will help us make the %s more compatible with your site and better at doing what you need it to.'=>'Regjistrohuni për të marrë njoftime me email për sigurinë dhe përditësimet e veçorive, përmbajtje edukative dhe oferta të rastësishme, si dhe për të ndarë disa informacione bazë mbi mjedisin e WordPress. Kjo do të na ndihmojë ta bëjmë %s më të përputhshëm me faqen tuaj dhe më efektiv në përmbushjen e nevojave tuaja.','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info.'=>'Regjistrohuni për të marrë njoftime me email për përditësimet e sigurisë dhe veçorive, përmbajtje edukative dhe oferta të herëpashershme, si dhe për të ndarë disa informacione bazë rreth mjedisit WordPress.','If you skip this, that\'s okay! %1$s will still work just fine.'=>'Nëse e kaloni këtë, nuk ka problem! %1$s do të vazhdojë të punojë siç duhet.','Allow & Continue'=>'Lejo dhe vazhdo','verbSkip'=>'Anulo','Skipping, please wait'=>'Duke kapërcyer, ju lutemi prisni','Continue'=>'Vazhdo','Please wait'=>'Ju lutemi prisni','as activating pluginActivating'=>'Duke u aktivizuar','This will allow %s to'=>'Kjo do t\'i lejojë %s-it të','Privacy Policy'=>'Politika e privatësisë','Terms of Service'=>'Kushtet e shërbimit','License Agreement'=>'Marrëveshja e Licencës','Have a license key?'=>'Keni një çelës licence?','Activate License'=>'Aktivizo licencën','View Basic Profile Info'=>'Shiko informacionin bazë të profileve','Your WordPress user\'s: first & last name, and email address'=>'Emri dhe mbiemri juaj i përdoruesit në WordPress, si dhe adresa e emailit','View Basic Website Info'=>'Shiko informacionin bazë të faqes së internetit','Homepage URL & title, WP & PHP versions, and site language'=>'URL-i dhe titulli i faqes kryesore, versionet e WP dhe PHP, si dhe gjuha e faqes','View Basic %s Info'=>'Shiko informacionin bazë për %s','Current %s & SDK versions, and if active or uninstalled'=>'%s aktuale & versionet e SDK-së, dhe nëse janë aktive ose të çinstaluara','Newsletter'=>'Buletini informativ','Updates, announcements, marketing, no spam'=>'Përditësime, njoftime, marketing, pa spam','View Diagnostic Info'=>'Shiko informacionin e diagnostikimit','WordPress & PHP versions, site language & title'=>'Versionet e WordPress & PHP, gjuha dhe titulli i faqes','View Plugins & Themes List'=>'Shiko listën e shtojcave dhe temave','Names, slugs, versions, and if active or not'=>'Emrat, fjalët kyçe të URL-së, versionet dhe nëse janë aktive apo jo','optional'=>'opsional','Never miss an important update'=>'Mos humbisni kurrë një përditësim të rëndësishëm','We have introduced this opt-in so you never miss an important update and help us make the %s more compatible with your site and better at doing what you need it to.'=>'Kemi prezantuar këtë opsion pranimi për t\'u siguruar që të mos humbisni kurrë një përditësim të rëndësishëm dhe për të na ndihmuar ta bëjmë %s më të pajtueshëm me faqen tuaj dhe më efikas në përmbushjen e nevojave tuaja.','Thank you for updating to %1$s v%2$s!'=>'Faleminderit për përditësimin në %1$s v%2$s!','The prefix must be 1 to 8 lowercase letters or digits, start with a letter, and must not name the plugin.'=>'Prefiksi duhet të ketë nga 1 deri në 8 shkronja të vogla ose shifra, të fillojë me një shkronjë dhe të mos ketë emrin e shtojcës.','"%s" is not a language code. Use a WordPress locale such as fr_FR or de_DE.'=>'"%s" nuk është një kod gjuhe. Përdorni një lokal të WordPress si fr_FR ose de_DE.','List at least one language.'=>'Listoni të paktën një gjuhë.','You are not allowed to translate this item.'=>'Nuk ju lejohet ta përktheni këtë artikull.','This item already has a version in that language.'=>'Ky artikull ka tashmë një version në atë gjuhë.','That translation engine is not available on this site.'=>'Ai motor përkthimi nuk është i disponueshëm në këtë faqe.','Different engines per language, automatic fallback and spending caps are Tranzly Pro features.'=>'Motorët e ndryshëm për çdo gjuhë, kthimi automatik në gjuhën bazë dhe kufijtë e shpenzimeve janë veçori të Tranzly Pro.','Each language must be one of the site\'s languages, with an available engine.'=>'Secila gjuhë duhet të jetë një nga gjuhët e faqes, me një motor të disponueshëm.','The fallback list may only name available engines.'=>'Lista e kthimit pas mund të emërtojë vetëm motorët e disponueshëm.','A monthly cap is an amount in US dollars, zero or more, for an available engine.'=>'Një kufi mujor është një shumë në dollarë US, zero ose më shumë, për një motor të disponueshëm.','Preferred translations and tone per language are Tranzly Pro features. The do-not-translate list is free.'=>'Përkthimet e preferuara dhe toni për çdo gjuhë janë veçori të Tranzly Pro. Lista e fjalëve që nuk duhet të përkthehen është falas.','Glossary entries must be grouped by one of the site\'s languages.'=>'Hyrjet e fjalorit duhet të grupohen sipas një prej gjuhëve të faqes.','Tone is set per site language: formality default, more or less, plus optional instructions.'=>'Tonet vendosen për çdo gjuhë të faqes: formaliteti si parazgjedhje, pak a shumë, plus udhëzime opsionale.','The value for %s is not one of the allowed choices.'=>'Vlera për %s nuk është një nga zgjedhjet e lejuara.','The background queue is not available on this site.'=>'Radha e prapavijës nuk është e disponueshme në këtë faqe.','A translation job runs as the person who starts it, so a user must be signed in.'=>'Një punë përkthimi ekzekutohet si personi që e nis atë, kështu që përdoruesi duhet të jetë i kyçur.','There is nothing you are allowed to translate in that selection.'=>'Nuk ka asgjë që ju lejohet të përktheni në atë përzgjedhje.','That item is not part of a translation job.'=>'Ky artikull nuk është pjesë e një pune përkthimi.','You are not allowed to change that translation.'=>'Nuk ju lejohet të ndryshoni atë përkthim.','This item\'s group already has a %1$s version (#%2$d).'=>'Grupi i këtij artikulli tashmë ka një version %1$s (#%2$d).','An item cannot be its own translation.'=>'Një artikull nuk mund të jetë përkthimi i vetvetes.','That item is already a translation of something else. Unlink it first.'=>'Ai element është tashmë një përkthim i diçkaje tjetër. Lidheni fillimisht.','The translation link could not be saved.'=>'Lidhja e përkthimit nuk mund të ruhej.','That text cannot be translated here.'=>'Ajo tekst nuk mund të përkthehet këtu.','That media text cannot be translated here.'=>'Ky tekst i mediave nuk mund të përkthehet këtu.','A translation can be published or kept as a draft.'=>'Një përkthim mund të publikohet ose të ruhet si draft.','You are not allowed to publish this kind of content.'=>'Nuk ju lejohet të publikoni këtë lloj përmbajtjeje.','This item is already written in that language.'=>'Ky artikull është shkruar tashmë në atë gjuhë.','This translation was edited by a person (or imported), so it is protected. Unlock it to translate it again.'=>'Ky përkthim është redaktuar nga një person (ose është importuar), kështu që është i mbrojtur. Zhbllokojeni për ta përkthyer përsëri.','No translation engine is set up yet. Add a key for one in Tranzly → Engines.'=>'Asnjë motor përkthimi nuk është konfiguruar ende. Shto një çelës për njërin te Tranzly → Engines.','That translation engine is not set up yet: add its key first.'=>'Ai motor përkthimi nuk është konfiguruar ende: shtoni çelësin e tij fillimisht.','The same text is being translated by another job right now; this item will use that answer.'=>'E njëjta tekst po përkthehet nga një detyrë tjetër tani; ky artikull do të përdorë atë përgjigje.','No translation engine could take this item.'=>'Asnjë motor përkthimi nuk mund ta merrte këtë artikull.','The engine did not return a translation for every part of this item. Nothing was changed.'=>'Motori nuk ktheu një përkthim për çdo pjesë të këtij artikulli. Asgjë nuk u ndryshua.','AI model'=>'Modeli AI','AI model (%1$s %2$s)'=>'Modeli i AI (%1$s %2$s)','%s is having problems right now. Try again shortly, or use another engine.'=>'%s pokalon probleme për momentin. Provoni përsëri pas pak, ose përdorni një tjetër motor.','Your site could not reach %s. Check that it can make outgoing connections, then try again.'=>'Sajti juaj nuk mund të lidhej me %s. Kontrolloni që ai mund të kryejë lidhje dalëse dhe provoni përsëri.','%s did not accept your API key. Check the key in Tranzly → Engines.'=>'%s nuk pranoi çelësin tuaj të API-së. Kontrolloni çelësin te Tranzly → Engines.','Your %s account has used up its quota or balance. Top it up with them, or use another engine.'=>'Llogaria juaj %s ka shfrytëzuar kuotën ose balancën e saj. Mbusheni atë me ta, ose përdorni një motor tjetër.','%s asked us to slow down. It will be tried again automatically.'=>'%s na kërkoi të ngadalësojmë. Do të provohet përsëri automatikisht.','This text is too long for %s in one go. Split the content, or use another engine.'=>'Ky tekst është shumë i gjatë për %s menjëherë. Ndani përmbajtjen ose përdorni një motor tjetër.','%s refused to translate this content. Try another engine, or translate it by hand.'=>'%s refuzoi ta përkthejë këtë përmbajtje. Provoni një motor tjetër ose përkthejeni vetë me dorë.','%s does not translate this language. Choose another engine for it.'=>'%s nuk e përkthen këtë gjuhë. Zgjidhni një motor tjetër për të.','This month\'s spending cap for %s is reached, so nothing more was sent to it. Raise the cap in Tranzly → Engines, or wait until next month.'=>'Kufiri i shpenzimeve për këtë muaj për %s është arritur, kështu që nuk u dërgua asgjë tjetër atje. Rritni kufirin te Tranzly → Engines, ose prisni deri muajin e ardhshëm.','The translation with %s failed for a reason Tranzly could not identify. The details are below.'=>'Përkthimi me %s dështoi për një arsye që Tranzly nuk mund ta identifikonte. Detajet janë më poshtë.','An engine id must be lowercase letters, digits and hyphens.'=>'Një ID e motorit duhet të përbëhet nga shkronja të vogla, shifra dhe viza.','Built by Neil Lock, CEO of Zinn Digital® Ltd'=>'Ndërtuar nga Neil Lock, CEO i Zinn Digital® Ltd','Version %s'=>'Versioni %s','Tranzly website'=>'Faqja e internetit Tranzly','Zinn Digital® website'=>'Faqja e internetit Zinn Digital®','Settings saved.'=>'Cilësimet u ruajtën.','See the Pro plans and pricing'=>'Shih planët dhe çmimet Pro','Languages'=>'Gjuhët','The first language is the one your content is written in. Visitors switch with the language switcher block.'=>'Gjuha e parë është ajo në të cilën është shkruar përmbajtja juaj. Vizitorët ndërrojnë gjuhën me bllokun e zgjedhjes së gjuhës.','(default)'=>'(parazgjedhur)','Locale code'=>'Kodi i lokalizimit','For example fr_FR'=>'Për shembull fr_FR','Name (optional)'=>'Emri (opsionale)','For example Français'=>'Për shembull Français','Add language'=>'Shto gjuhë','Front-end output'=>'Dalja e front-end-it','Class name prefix'=>'Prefiksi i emrit të klasës','Every class name the plugin prints on your pages starts with this prefix, so the pages do not reveal which plugin built them. 1 to 8 lowercase letters or digits, starting with a letter.'=>'Çdo emër klase që shtojca shfaq në faqet tuaja fillon me këtë prefiks, kështu që faqet nuk tregojnë se cila shtojcë i ka ndërtuar ato. 1 deri në 8 shkronja të vogla ose shifra, duke filluar me një shkronjë.','Beta updates'=>'Përditësimet beta','This site receives beta versions as updates.'=>'Kjo faqe merr versione beta si përditësime.','This site receives stable versions only.'=>'Ky sajt merr vetëm versione të qëndrueshme.','Change this on the Account page'=>'Ndryshoni këtë në faqen e Llogarisë','Beta versions are offered to licensed Pro installations that are connected to their account. Once connected, you can join from the Account page.'=>'Versionet Beta u ofrohen instalimeve të licensuara Pro që janë të lidhura me llogarinë e tyre. Pasi të jeni lidhur, mund të bashkoheni nga faqja e Llogarisë.','Save settings'=>'Ruaj cilësimet','First engine that is set up'=>'Motori i parë që është konfiguruar','Key saved. It is stored encrypted and never shown again.'=>'Çelësi u ruajt. Ai ruhet i enkriptuar dhe nuk shfaqet më kurrë.','Engine settings saved.'=>'Cilësimet e motorit u ruajtën.','Glossary saved.'=>'Fjalori u ruajt.','Your keys'=>'Çelësat tuaj','Tranzly calls the translation services with your own account. Keys are stored encrypted in your database and are only ever sent to the service they belong to. AI model keys are set in the AI settings.'=>'Tranzly thërret shërbimet e përkthimit me llogarinë tuaj. Çelësat ruhen të enkoduar në bazën tuaj të të dhënave dhe dërgohen vetëm te shërbimi të cilit i përkasin. Çelësat e modelit të AI-së vendosen te cilësimet e AI-së.','%s API key'=>'%s çelësi API','Saved: %s. Enter a new key to replace it, or save an empty field to remove it.'=>'Ruajtur: %s. Futni një çelës të ri për ta zëvendësuar, ose ruani një fushë të zbrazët për ta hequr.','No key saved.'=>'Nuk ka çelës të ruajtur.','Azure region (leave empty for a global resource)'=>'Rajoni i Azure (lëreni bosh për një burim global)','Save key'=>'Ruaj çelësin','Check my DeepL usage'=>'Kontrollo përdorimin tim të DeepL','%1$s of %2$s characters used this billing period.'=>'%1$s nga %2$s karaktere të përdorura në këtë periudhë faturimi.','Which engine translates'=>'Cili motor përkthen','No engine is set up yet. Save a key above (or set up an AI model) to start translating.'=>'Nuk është caktuar ende asnjë motor. Ruani një çelës më lart (ose konfiguroni një model AI) për të filluar përkthimin.','Default engine'=>'Motori i paracaktuar','A different engine per language, automatic fallback and monthly spending caps are Tranzly Pro features.'=>'Një motor i ndryshëm për çdo gjuhë, kthimi automatik në gjuhën parazgjedhje dhe kufijtë e shpenzimeve mujore janë veçori të Tranzly Pro.','Engine for %s'=>'Motori për %s','The default engine'=>'Motori i paracaktuar','If an engine fails or reaches a limit, try these next, in this order'=>'Nëse një motor dështon ose arrin një kufizim, provoni këto më poshtë, në këtë renditje','Monthly spending caps'=>'Kufizimet mujore të shpenzimeve','When an engine reaches its cap, nothing more is sent to it until next month and the failed-translation report says why. Leave empty for no cap.'=>'Kur një motor arrit kufirin e tij, asgjë tjetër nuk i dërgohet deri në muajin e ardhshëm dhe raporti i përkthimeve të dështuara tregon arsyen. Lëreni bosh për të mos vendosur kufi.','%1$s (spent this month: $%2$s)'=>'%1$s (shpenzuar këtë muaj: $%2$s)','Save caps'=>'Ruaj shkronjat e mëdha','Glossary and words never translated'=>'Fjalor dhe fjalë që nuk përkthehen kurrë','Never translate these words (one per line)'=>'Mos i përkthe kurrë këto fjalë (një për rresht)','Brand and product names stay exactly as they are, with every engine.'=>'Emrat e markave dhe produkteve mbeten saktësisht ashtu siç janë, me çdo motor.','Preferred translations and tone per language are Tranzly Pro features.'=>'Përkthimet e preferuara dhe toni sipas gjuhës janë veçori të Tranzly Pro.','Preferred translations (one per line: term = translation)'=>'Përkthimet e preferuara (një për rresht: termi = përkthimi)','Formality'=>'Formaliteti','Default'=>'Parazgjedhur','Formal'=>'Formal','Informal'=>'Jozyrtar','Style instructions (audience, brand voice)'=>'Udhëzimet e stileve (audienca, toni i markës)','Save glossary'=>'Ruaj fjalorin','Job started with %d translations to do. It runs in the background: you can close this page.'=>'Puna filloi me %d përkthime për t\'u bërë. Ajo ekzekutohet në sfond: mund ta mbyllni këtë faqe.','Queued again.'=>'Në pritje përsëri.','Running'=>'Duke u ekzekutuar','Finished'=>'Përfunduar','Cancelled'=>'Anuluar','Translate in the background'=>'Përkthe në sfond','Set up a translation engine in the Engines tab first.'=>'Konfiguroni një motor përkthimi në skedën Motorët më parë.','Translate every'=>'Përkthe çdo','Into'=>'Në','With'=>'Me','Each language’s own engine'=>'Motori i çdo gjuhe','Publish the translations (otherwise they are saved as drafts)'=>'Publikoni përkthimet (përndryshe ato ruhen si skica)','Estimate the cost'=>'Vlerësoni koston','%1$d posts, %2$s characters. The price for this engine is not known in advance.'=>'%1$d postime, %2$s karaktere. Çmimi për këtë motor nuk dihet paraprakisht.','%1$d posts, %2$s characters: about $%3$s on your own account.'=>'%1$d postime, %2$s karaktere: rreth $%3$s në llogarinë tuaj.','Start translating'=>'Fillo përkthimin','Jobs'=>'Detyra','No translation jobs yet.'=>'Nuk ka ende detyra përkthimi.','Job %1$d — %2$s'=>'Detyra %1$d — %2$s','%1$d of %2$d translated, %3$d failed, %4$d skipped (protected or already in that language)'=>'%1$d nga %2$d të përkthyera, %3$d dështuan, %4$d u anashkaluan (të mbrojtura ose tashmë në atë gjuhë)','Stop this job'=>'Ndalo këtë detyrë','See what failed and why'=>'Shihni se çfarë dështoi dhe pse','Content'=>'Përmbajtja','Language'=>'Gjuha','What went wrong'=>'Çka shkoi keq','Fix it'=>'Rregulloje','Details'=>'Detajet','Retry with'=>'Provo sërish me','The same engine'=>'I triedur e njëjtë','Retry'=>'Provo sërish','Translate by hand'=>'Përkthe dorazi','Languages and settings'=>'Gjuha dhe cilësimet','Engines'=>'Motorët','Translation jobs'=>'Detyrat e përkthimit','Add a second language under Tranzly in the admin menu, and the switcher appears here.'=>'Shtoni një gjuhë të dytë te Tranzly në menujën e administrimit dhe ndërruesi do të shfaqet këtu.','Switcher'=>'Ndërrues','Accessible label'=>'Etiketa e aksesueshme','block titleLanguage switcher'=>'Zgjedhësi i gjuhës','block descriptionLinks to this page in each of the site\'s languages. It renders nothing until two or more languages are listed.'=>'Lidhjet me këtë faqe në secilën nga gjuhët e faqes. Nuk shfaq asgjë derisa të jenë listuar dy ose më shumë gjuhë.','block keywordlanguage'=>'Gjuha','block keywordswitcher'=>'ndërrues','block keywordtranslation'=>'përkthim']];